<div><form wire:submit="{{ $editingInspectionId === null ? 'save' : 'update' }}"><input wire:model="title" placeholder="Inspection title"><input wire:model="templateKey" placeholder="Template key"><button type="submit">{{ $editingInspectionId === null ? 'Create inspection' : 'Update inspection' }}</button>@if ($editingInspectionId !== null)<button type="button" wire:click="cancelEdit">Cancel</button>@endif</form>@error('title')<p>{{ $message }}</p>@enderror<ul>@forelse($inspections as $inspection)<li wire:key="inspection-{{ $inspection->id }}">{{ $inspection->title }} ({{ $inspection->status }}) <button type="button" wire:click="edit({{ $inspection->id }})">Edit</button>@if ($inspection->status === 'draft')<select wire:model="outcome"><option value="pass">Pass</option><option value="fail">Fail</option><option value="conditional">Conditional</option></select><button type="button" wire:click="complete({{ $inspection->id }})">Complete</button>@endif<button type="button" wire:click="delete({{ $inspection->id }})">Delete</button></li>@empty<li>No inspections yet.</li>@endforelse</ul></div>
